import { useCallback, useEffect, useRef, useState } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [view, setView] = useState({ results: [], phase: "idle" });

  const valueRef = useRef("");
  const timerRef = useRef(null);
  const latestRequestRef = useRef(null);
  const mountedRef = useRef(false);

  const clearTimer = useCallback(() => {
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const resetSearch = useCallback(() => {
    clearTimer();

    const previous = latestRequestRef.current;
    latestRequestRef.current = null;
    if (previous) {
      previous.controller.abort();
    }

    setView({ results: [], phase: "idle" });
  }, [clearTimer]);

  const startRequest = useCallback(
    (query, force = false) => {
      clearTimer();

      if (!mountedRef.current) {
        return;
      }

      if (query.length < minChars) {
        resetSearch();
        return;
      }

      const previous = latestRequestRef.current;
      if (
        !force &&
        previous &&
        previous.query === query &&
        (previous.status === "pending" || previous.status === "success")
      ) {
        return;
      }

      const controller = new AbortController();
      const request = { query, controller, status: "pending" };

      // Invalidate the previous request before its abort listeners can run.
      latestRequestRef.current = request;
      if (previous) {
        previous.controller.abort();
      }

      setView((current) => ({
        results: current.results,
        phase: "loading",
      }));

      const isCurrent = () =>
        mountedRef.current &&
        latestRequestRef.current === request &&
        !controller.signal.aborted;

      const onSuccess = (results) => {
        if (!isCurrent()) {
          return;
        }

        request.status = "success";
        setView({ results, phase: "success" });
      };

      const onFailure = (error) => {
        if (!isCurrent()) {
          return;
        }

        if (error && error.name === "AbortError") {
          request.status = "aborted";
          setView((current) => ({
            results: current.results,
            phase: "idle",
          }));
          return;
        }

        request.status = "failed";
        setView({ results: [], phase: "error" });
      };

      try {
        Promise.resolve(search(query, { signal: controller.signal })).then(
          onSuccess,
          onFailure
        );
      } catch (error) {
        onFailure(error);
      }
    },
    [clearTimer, minChars, resetSearch, search]
  );

  const scheduleSearch = useCallback(
    (nextValue) => {
      clearTimer();

      const query = nextValue.trim();
      if (query.length < minChars) {
        resetSearch();
        return;
      }

      const timer = setTimeout(() => {
        if (timerRef.current !== timer) {
          return;
        }

        timerRef.current = null;
        startRequest(query);
      }, debounceMs);

      timerRef.current = timer;
    },
    [clearTimer, debounceMs, minChars, resetSearch, startRequest]
  );

  useEffect(() => {
    mountedRef.current = true;

    return () => {
      mountedRef.current = false;
      clearTimer();

      const previous = latestRequestRef.current;
      latestRequestRef.current = null;
      if (previous) {
        previous.controller.abort();
      }
    };
  }, [clearTimer]);

  // Handle the initial value and configuration changes. Typing schedules
  // directly in the event handler, including changes to whitespace alone.
  useEffect(() => {
    scheduleSearch(valueRef.current);
    return clearTimer;
  }, [clearTimer, scheduleSearch]);

  function handleChange(event) {
    const nextValue = event.target.value;
    valueRef.current = nextValue;
    setValue(nextValue);
    scheduleSearch(nextValue);
  }

  function handleRetry() {
    startRequest(valueRef.current.trim(), true);
  }

  const statusText =
    view.phase === "loading"
      ? "Searching..."
      : view.phase === "success" && view.results.length === 0
        ? "No results"
        : "";

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{statusText}</div>
      <ul aria-label="Results">
        {view.results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
      {view.phase === "error" && (
        <div role="alert">
          Something went wrong
          <button type="button" onClick={handleRetry}>
            Retry
          </button>
        </div>
      )}
    </div>
  );
}
